function processNumbers(arr) {
  // Check for null or undefined inputs and handle them by returning an empty array
  if (arr == null) {
    return [];
  }

  // Ensure the input is an array. If not, return an empty array.
  if (!Array.isArray(arr)) {
    return [];
  }

  // Filter the array to include only numeric values
  return arr.filter(item => typeof item === 'number' && item % 2 === 0) // Keep even numbers only
            .map(evenNumber => evenNumber * 2); // Multiply each even number by 2
}

// Example usage:
console.log(processNumbers([1, 2, 3, 4, 'a', null, 6])); // Output: [4, 8, 12]
console.log(processNumbers([])); // Output: []
console.log(processNumbers(null)); // Output: []
console.log(processNumbers([1, "b", undefined, 3])); // Output: []
console.log(processNumbers([2, 5, 8, 13])); // Output: [4, 16]
```

### Explanation:
1. **Null/Undefined Handling**: The function initially checks if `arr` is `null` or `undefined` and returns an empty array if so. This is done using `arr == null`, which caters to both `null` and `undefined`.

2. **Non-Array Input**: We check if the input is an array using `Array.isArray(arr)`. If it's not an array, return an empty array to ensure we process only valid array inputs.

3. **Non-Numeric Values**: We filter out non-numeric values by checking if the type of each item is `"number"` and if it's an even number using `item % 2 === 0`.

4. **Transformation**: Once filtered for numeric and even values, we then map over the array and multiply each number by 2.

This function is robust to handle various edge cases and ensures that the input is processed correctly.

