Here is a JavaScript class called `UserManager` that manages a collection of user objects with the specified properties and methods. The class includes validation for email format and age, and throws appropriate errors for invalid operations:

```javascript
class UserManager {
  constructor() {
    this.users = [];
    this.nextId = 1;
  }

  isValidEmail(email) {
    // Simple regex for email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  isValidAge(age) {
    return Number.isInteger(age) && age > 0;
  }

  addUser(user) {
    if (!user.name || !user.email || !user.age) {
      throw new Error('User must have name, email, and age.');
    }

    if (!this.isValidEmail(user.email)) {
      throw new Error('Invalid email format.');
    }

    if (!this.isValidAge(user.age)) {
      throw new Error('Age must be a positive integer.');
    }

    user.id = this.nextId++;
    this.users.push(user);
    return user;
  }

  getUserById(id) {
    const user = this.users.find(user => user.id === id);
    if (!user) {
      throw new Error(`User with id ${id} not found.`);
    }
    return user;
  }

  updateUser(id, updates) {
    const user = this.getUserById(id);

    if (updates.email && !this.isValidEmail(updates.email)) {
      throw new Error('Invalid email format.');
    }

    if (updates.age && !this.isValidAge(updates.age)) {
      throw new Error('Age must be a positive integer.');
    }

    Object.assign(user, updates);
    return user;
  }

  deleteUser(id) {
    const userIndex = this.users.findIndex(user => user.id === id);
    if (userIndex === -1) {
      throw new Error(`User with id ${id} not found.`);
    }
    this.users.splice(userIndex, 1);
    return true;
  }

  getAllUsers() {
    return this.users;
  }
}

// Example usage:
const userManager = new UserManager();
try {
  userManager.addUser({ name: 'John Doe', email: 'john.doe@example.com', age: 30 });
  userManager.addUser({ name: 'Jane Smith', email: 'jane.smith@example.com', age: 25 });
  console.log(userManager.getAllUsers());
  const user = userManager.getUserById(1);
  console.log('User found:', user);
  userManager.updateUser(1, { age: 31 });
  console.log('Updated user:', userManager.getUserById(1));
  userManager.deleteUser(2);
  console.log('All users:', userManager.getAllUsers());
} catch (error) {
  console.error(error.message);
}
```

### Key Features:
- **Email Validation:** Uses a basic regex to ensure the email is in a standard format.
- **Age Validation:** Ensures the age is a positive integer.
- **Error Handling:** Throws errors for missing required properties, invalid email formats, invalid ages, and operations on non-existent users.
- **Dynamic ID Assignment:** Automatically assigns a unique ID to each user.

